import{u as e,o,c as r,a2 as s}from"./chunks/framework.DZhUhjDB.js";const d=JSON.parse('{"title":"Las 10 mejores comunidades de ciberseguridad","description":"Discords, foros, redes sociales y eventos para conectarte","frontmatter":{"title":"Las 10 mejores comunidades de ciberseguridad","description":"Discords, foros, redes sociales y eventos para conectarte","author":"Equipo CDPN","date":"2026-07-20T00:00:00.000Z","tags":["comunidad","networking","discord","eventos"],"readingTime":"3 min"},"headers":[],"relativePath":"blog/08-comunidades.md","filePath":"blog/08-comunidades.md","lastUpdated":1787323329000}'),n={name:"blog/08-comunidades.md"},u=Object.assign(n,{setup(i){const{frontmatter:t}=e();return(l,a)=>(o(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="las-10-mejores-comunidades-de-ciberseguridad" tabindex="-1">Las 10 mejores comunidades de ciberseguridad <a class="header-anchor" href="#las-10-mejores-comunidades-de-ciberseguridad" aria-label="Permalink to &quot;Las 10 mejores comunidades de ciberseguridad&quot;">​</a></h1><div class="article-meta"><span class="accent">📝 Equipo CDPN</span><span>📅 20 Julio 2026</span><span>📖 3 min de lectura</span><span>🏷️ Comunidad</span><span>🏷️ Networking</span></div><h2 id="¿por-que-importa-la-comunidad" tabindex="-1">¿Por qué importa la comunidad? <a class="header-anchor" href="#¿por-que-importa-la-comunidad" aria-label="Permalink to &quot;¿Por qué importa la comunidad?&quot;">​</a></h2><p>La ciberseguridad es un campo que <strong>evoluciona constantemente</strong>. Estar conectado con otros profesionales te mantiene actualizado y abierto a oportunidades.</p><h2 id="top-10-comunidades" tabindex="-1">Top 10 comunidades <a class="header-anchor" href="#top-10-comunidades" aria-label="Permalink to &quot;Top 10 comunidades&quot;">​</a></h2><h3 id="_1-🛡️-cdpn-cyberdefense-pro-network" tabindex="-1">1. 🛡️ CDPN (CyberDefense Pro Network) <a class="header-anchor" href="#_1-🛡️-cdpn-cyberdefense-pro-network" aria-label="Permalink to &quot;1. 🛡️ CDPN (CyberDefense Pro Network)&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Plataforma de aprendizaje + Discord</li><li><strong>Para qué</strong>: Labs interactivos, gamificación, roles profesionales</li><li><strong>Enlace</strong>: <a href="/CyberDefense-Pro-Network/campus/">CyberDefense Pro Network</a></li></ul><h3 id="_2-🔴-hack-the-box" tabindex="-1">2. 🔴 Hack The Box <a class="header-anchor" href="#_2-🔴-hack-the-box" aria-label="Permalink to &quot;2. 🔴 Hack The Box&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Plataforma de CTFs y máquinas</li><li><strong>Para qué</strong>: Practicar pentesting real</li><li><strong>Enlace</strong>: hackthebox.com</li></ul><h3 id="_3-🟢-tryhackme" tabindex="-1">3. 🟢 TryHackMe <a class="header-anchor" href="#_3-🟢-tryhackme" aria-label="Permalink to &quot;3. 🟢 TryHackMe&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Plataforma de aprendizaje guiado</li><li><strong>Para qué</strong>: Principiantes, rutas de aprendizaje</li><li><strong>Enlace</strong>: tryhackme.com</li></ul><h3 id="_4-🟡-owasp" tabindex="-1">4. 🟡 OWASP <a class="header-anchor" href="#_4-🟡-owasp" aria-label="Permalink to &quot;4. 🟡 OWASP&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Organización open source</li><li><strong>Para qué</strong>: Seguridad de aplicaciones, chapters locales</li><li><strong>Enlace</strong>: owasp.org</li></ul><h3 id="_5-🔵-r-netsec-reddit" tabindex="-1">5. 🔵 r/netsec (Reddit) <a class="header-anchor" href="#_5-🔵-r-netsec-reddit" aria-label="Permalink to &quot;5. 🔵 r/netsec (Reddit)&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Foro</li><li><strong>Para qué</strong>: Noticias, discusiones, recursos</li><li><strong>Enlace</strong>: reddit.com/r/netsec</li></ul><h3 id="_6-🟣-infosec-community-discord" tabindex="-1">6. 🟣 InfoSec Community (Discord) <a class="header-anchor" href="#_6-🟣-infosec-community-discord" aria-label="Permalink to &quot;6. 🟣 InfoSec Community (Discord)&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Discord con miles de miembros</li><li><strong>Para qué</strong>: Chat en tiempo real, ayuda, eventos</li><li><strong>Enlace</strong>: infosec.comunities</li></ul><h3 id="_7-🎯-bugcrowd-hackerone" tabindex="-1">7. 🎯 Bugcrowd / HackerOne <a class="header-anchor" href="#_7-🎯-bugcrowd-hackerone" aria-label="Permalink to &quot;7. 🎯 Bugcrowd / HackerOne&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Bug bounty programs</li><li><strong>Para qué</strong>: Ganar dinero resolviendo vulnerabilidades</li><li><strong>Enlace</strong>: bugcrowd.com, hackerone.com</li></ul><h3 id="_8-📚-pentesterlab" tabindex="-1">8. 📚 PentesterLab <a class="header-anchor" href="#_8-📚-pentesterlab" aria-label="Permalink to &quot;8. 📚 PentesterLab&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Labs de práctica</li><li><strong>Para qué</strong>: Ejercicios guiados de pentesting</li><li><strong>Enlace</strong>: pentesterlab.com</li></ul><h3 id="_9-🎙️-security-weekly" tabindex="-1">9. 🎙️ Security Weekly <a class="header-anchor" href="#_9-🎙️-security-weekly" aria-label="Permalink to &quot;9. 🎙️ Security Weekly&quot;">​</a></h3><ul><li><strong>Tipo</strong>: Podcast / YouTube</li><li><strong>Para qué</strong>: Entrevistas a expertos, noticias</li><li><strong>Enlace</strong>: securityweekly.com</li></ul><h3 id="_10-🌐-conferencias" tabindex="-1">10. 🌐 Conferencias <a class="header-anchor" href="#_10-🌐-conferencias" aria-label="Permalink to &quot;10. 🌐 Conferencias&quot;">​</a></h3><ul><li><strong>DEF CON</strong> — La más grande del mundo</li><li><strong>Black Hat</strong> — La más profesional</li><li><strong>BSides</strong> — Locales y accesibles</li><li><strong>RootedCON</strong> — En español (España)</li></ul><h2 id="tips-para-participar" tabindex="-1">Tips para participar <a class="header-anchor" href="#tips-para-participar" aria-label="Permalink to &quot;Tips para participar&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. No seas spectator — Contribuye, ayuda, comparte</span></span>
<span class="line"><span>2. Crea contenido — Writeups, blogs, videos</span></span>
<span class="line"><span>3. Asiste a eventos — Presenciales u online</span></span>
<span class="line"><span>4. Haz networking — Conecta con profesionales</span></span>
<span class="line"><span>5. Sé respetuoso — La comunidad se basa en confianza</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La ciberseguridad es una comunidad <strong>increíblemente abierta y colaborativa</strong>. Únete, aprende, contribuye. El conocimiento compartido nos hace más fuertes a todos.</p><hr><p><em>Artículo publicado en el Blog CDPN — Semana 8</em></p>`,31)])]))}});export{d as __pageData,u as default};
